layout(std430, binding = 0) readonly buffer Terrain { float H[]; };
layout(std430, binding = 1) readonly buffer PIn { vec2 P[]; };
layout(std430, binding = 2) readonly buffer Flux { vec4 F[]; };
layout(std430, binding = 3) writeonly buffer POut { vec2 Q[]; };
layout(push_constant) uniform PC { uint SZ; float k; float rain; } pc;

// Packed-state height pass. Surface is recomputed exactly from terrain
// (S' = H + W') rather than accumulated incrementally, so no drift between
// the water and surface fields over long runs.
void main() {
    int SZ = int(pc.SZ);
    int x = int(gl_GlobalInvocationID.x), y = int(gl_GlobalInvocationID.y);
    if (x >= SZ || y >= SZ) return;
    uint i = uint(y) * uint(SZ) + uint(x);
    int xl = max(x - 1, 0), xr = min(x + 1, SZ - 1);
    int yu = max(y - 1, 0), yd = min(y + 1, SZ - 1);
    uint iL = uint(y) * uint(SZ) + uint(xl);
    uint iR = uint(y) * uint(SZ) + uint(xr);
    uint iU = uint(yu) * uint(SZ) + uint(x);
    uint iD = uint(yd) * uint(SZ) + uint(x);
    float mL = float(x > 0), mR = float(x < SZ - 1);
    float mU = float(y > 0), mD = float(y < SZ - 1);
    vec4 fi = F[i];
    float outflow = fi.x + fi.y + fi.z + fi.w;
    float inflow = F[iL].y * mL + F[iR].x * mR + F[iU].w * mU + F[iD].z * mD;
    float w = P[i].x + pc.rain - outflow + inflow;
    Q[i] = vec2(w, H[i] + w);
}

inputs.shader:
#version 450
layout(local_size_x = 16, local_size_y = 16) in;
layout(std430, binding = 0) readonly buffer Terrain { float H[]; };
layout(std430, binding = 1) readonly buffer PIn { vec2 P[]; };
layout(std430, binding = 2) writeonly buffer Flux { vec4 F[]; };
layout(push_constant) uniform PC { uint SZ; float k; float rain; } pc;

// Strip-mined flux pass: each invocation handles 4 consecutive rows,
// amortizing the fixed per-invocation launch cost over more stencil work.
void main() {
    int SZ = int(pc.SZ);
    int x = int(gl_GlobalInvocationID.x);
    int y0 = int(gl_GlobalInvocationID.y) * 4;
    if (x >= SZ) return;
    int xl = max(x - 1, 0), xr = min(x + 1, SZ - 1);
    for (int s = 0; s < 4; ++s) {
        int y = y0 + s;
        if (y >= SZ) break;
        uint i = uint(y) * uint(SZ) + uint(x);
        int yu = max(y - 1, 0), yd = min(y + 1, SZ - 1);
        vec2 pc_i = P[i];
        float hi = pc_i.y;
        float fL = max(0.0, pc.k * (hi - P[uint(y) * uint(SZ) + uint(xl)].y));
        float fR = max(0.0, pc.k * (hi - P[uint(y) * uint(SZ) + uint(xr)].y));
        float fU = max(0.0, pc.k * (hi - P[uint(yu) * uint(SZ) + uint(x)].y));
        float fD = max(0.0, pc.k * (hi - P[uint(yd) * uint(SZ) + uint(x)].y));
        float tot = fL + fR + fU + fD;
        float wi = pc_i.x;
        float ss = wi / max(tot, max(wi, 1e-20));
        fL *= ss; fR *= ss; fU *= ss; fD *= ss;
        F[i] = vec4(fL, fR, fU, fD);
    }
}

