layout(std430, binding = 2) writeonly buffer Flux { vec4 F[]; };
layout(push_constant) uniform PC { uint SZ; float k; float rain; } pc;

// Strip-mined flux pass: each invocation handles 4 consecutive rows,
// amortizing the fixed per-invocation launch cost over more stencil work.
void main() {
    int SZ = int(pc.SZ);
    int x = int(gl_GlobalInvocationID.x);
    int y0 = int(gl_GlobalInvocationID.y) * 4;
    if (x >= SZ) return;
    int xl = max(x - 1, 0), xr = min(x + 1, SZ - 1);
    for (int s = 0; s < 4; ++s) {
        int y = y0 + s;
        if (y >= SZ) break;
        uint i = uint(y) * uint(SZ) + uint(x);
        int yu = max(y - 1, 0), yd = min(y + 1, SZ - 1);
        vec2 pc_i = P[i];
        float hi = pc_i.y;
        float fL = max(0.0, pc.k * (hi - P[uint(y) * uint(SZ) + uint(xl)].y));
        float fR = max(0.0, pc.k * (hi - P[uint(y) * uint(SZ) + uint(xr)].y));
