#version 450
layout(local_size_x = 16, local_size_y = 16) in;
layout(std430, binding = 0) readonly buffer Terrain { float H[]; };
layout(std430, binding = 1) readonly buffer PIn { vec2 P[]; };
layout(std430, binding = 2) readonly buffer Flux { vec4 F[]; };
layout(std430, binding = 3) writeonly buffer POut { vec2 Q[]; };
layout(push_constant) uniform PC { uint SZ; float k; float rain; } pc;

// Strip-mined height pass: same 4-rows-per-invocation strategy as the flux pass.
void main() {
    int SZ = int(pc.SZ);
    int x = int(gl_GlobalInvocationID.x);
    int y0 = int(gl_GlobalInvocationID.y) * 4;
    if (x >= SZ) return;
    int xl = max(x - 1, 0), xr = min(x + 1, SZ - 1);
    float mL = float(x > 0), mR = float(x < SZ - 1);
    for (int s = 0; s < 4; ++s) {
        int y = y0 + s;
        if (y >= SZ) break;
        uint i = uint(y) * uint(SZ) + uint(x);
        int yu = max(y - 1, 0), yd = min(y + 1, SZ - 1);
        uint iL = uint(y) * uint(SZ) + uint(xl);
        uint iR = uint(y) * uint(SZ) + uint(xr);
        uint iU = uint(yu) * uint(SZ) + uint(x);
        uint iD = uint(yd) * uint(SZ) + uint(x);
        float mU = float(y > 0), mD = float(y < SZ - 1);
        vec4 fi = F[i];
        float outflow = fi.x + fi.y + fi.z + fi.w;
        float inflow = F[iL].y * mL + F[iR].x * mR + F[iU].w * mU + F[iD].z * mD;
        float w = P[i].x + pc.rain - outflow + inflow;
        Q[i] = vec2(w, H[i] + w);
    }
}

